import { NextRequest, NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth/options";
import { db } from "@/lib/storage";

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: "Unauthorized" },
        { status: 401 }
      );
    }

    const body = await request.json();
    const { scanId1, scanId2 } = body;

    if (!scanId1 || !scanId2) {
      return NextResponse.json(
        { error: "Both scanId1 and scanId2 are required" },
        { status: 400 }
      );
    }

    const [scan1, scan2] = await Promise.all([
      db.findById<{ id: string; user_id: string; status: string; items_count: number; agent_summary?: string | null; created_at: string }>("scans", scanId1),
      db.findById<{ id: string; user_id: string; status: string; items_count: number; agent_summary?: string | null; created_at: string }>("scans", scanId2),
    ]);

    if (!scan1 || scan1.user_id !== session.user.id) {
      return NextResponse.json(
        { error: "Scan 1 not found or unauthorized" },
        { status: 404 }
      );
    }

    if (!scan2 || scan2.user_id !== session.user.id) {
      return NextResponse.json(
        { error: "Scan 2 not found or unauthorized" },
        { status: 404 }
      );
    }

    const [dishes1, dishes2] = await Promise.all([
      db.findBy<{ id: string; scan_id: string; name: string; description?: string; price?: number; category?: string; image_url?: string; dietary_tags: string[] }>("dishes", { scan_id: scanId1 }),
      db.findBy<{ id: string; scan_id: string; name: string; description?: string; price?: number; category?: string; image_url?: string; dietary_tags: string[] }>("dishes", { scan_id: scanId2 }),
    ]);

    return NextResponse.json({
      scan1: { ...scan1, dishes: dishes1 },
      scan2: { ...scan2, dishes: dishes2 },
    });
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : "Failed to compare scans";
    return NextResponse.json({ error: message }, { status: 500 });
  }
}
